args.sparql:
SELECT ?film ?filmLabel ?director ?dirLabel ?birthDate WHERE {
  VALUES ?film { dbr:A.P.E.X. dbr:Quax_in_Africa }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?birthDate }
  OPTIONAL { ?director rdfs:label ?dirLabel FILTER (lang(?dirLabel)='en') }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel)='en') }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?film ?filmLabel ?director ?dirLabel ?birthDate WHERE {
  VALUES ?film { <http://dbpedia.org/resource/A.P.E.X.> <http://dbpedia.org/resource/Quax_in_Africa> }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?birthDate }
  OPTIONAL { ?director rdfs:label ?dirLabel FILTER (lang(?dirLabel)='en') }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel)='en') }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?film ?filmLabel ?director ?dirLabel ?birthDate WHERE {
  ?film a dbo:Film ; rdfs:label ?filmLabel ; dbo:director ?director .
  FILTER(langMatches(lang(?filmLabel),'EN'))
  FILTER( regex(?filmLabel, "^A\\.P\\.E\\.X\\.$", "i") || regex(?filmLabel, "Quax in Africa", "i") )
  OPTIONAL { ?director dbo:birthDate ?birthDate }
  OPTIONAL { ?director rdfs:label ?dirLabel FILTER (lang(?dirLabel)='en') }
}

